    removed = sorted(key for key in os.environ if key.startswith("HEPTA_"))
    for key in removed:
        os.environ.pop(key)
    compiler_raw = compiler.read_bytes()
    if sha256(compiler_raw).hexdigest() != "81b6fad94493546b5bf3f858248f25b19aded88bf8f3aaad18140aa317dac109":
        raise AssertionError("retained development compiler identity differs")
    original_materialization = json.loads((root / "development-evidence/code-port-r1/materialization.json").read_bytes())
    pins = {}
    for name, record in original_materialization["files"].items():
        raw = (root / name).read_bytes()
        if identity(raw) != record["expected"]:
            raise AssertionError("frozen port differs before original observation: " + name)
        pins[name] = identity(raw)
        path = out / "frozen-inputs" / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(raw)
    (out / "compiler.input.bin").write_bytes(compiler_raw)
    report = {"schema": "hepta.hia.code-composition-original-observations.v75-r1",
              "status": "RUNNING", "scope": "PYTHON_3_12_DEVELOPMENT_ONLY",
              "python": sys.version, "source_directory": str(root),
              "source_is_complete_git_checkout": False, "source_before": pins,
              "removed_selector_names": removed, "compiler": {"path": str(compiler), **identity(compiler_raw)},
              "claims": {"cold_qualified": False, "whole_native_qualified": False,
                         "default_flipped": False, "legacy_deleted": False},
              "compilations": [], "differentials": []}
    target = out / "REPORT.json"
    write(target, report)
    started = time.monotonic()
    try:
        from tools.qualify_hia_selfhost import compile_stage
        manifests = {}
        for part, schema_version in (("encoding", 2), ("state", 1), ("instructions", 1)):
            directory = out / part
            directory.mkdir(mode=0o700)
            raw = (root / ("examples/hia_bootstrap/machine_" + part + ".hiaasm")).read_bytes()
            image, receipt = compile_stage(directory, "machine-" + part, compiler, raw)
            manifest = {"schema": "hepta.hia.machine-" + part + "-native.v" + str(schema_version),
                        "source_sha256": sha256(raw).hexdigest(), "image_path": image.name,
                        "image_sha256": sha256(image.read_bytes()).hexdigest(),
                        "compiler_sha256": sha256(compiler_raw).hexdigest()}
            path = directory / "manifest.json"
            write(path, manifest)
            manifests[part] = path
            report["compilations"].append({"part": part, "manifest": manifest, "receipt": receipt,
                                            "manifest_path": str(path)})
            write(target, report)
            print(json.dumps({"part": part, "native_compile_status": receipt["status"],
                              "image_sha256": manifest["image_sha256"]}), flush=True)
        from hepta import hia_machine_x64 as reference
        from hepta import hia_machine_encoding_native as byte_bridge
        from hepta import hia_machine_state_native as state_bridge
        from hepta import hia_machine_instructions_native as instruction_bridge
        images = {"encoding": byte_bridge.installed_machine_encoding(str(manifests["encoding"])),
                  "state": state_bridge.installed_machine_state(str(manifests["state"])),
                  "instructions": instruction_bridge.installed_machine_instructions(str(manifests["instructions"]))}
        selectors = {byte_bridge.SELECTOR: str(manifests["encoding"]),
                     state_bridge.SELECTOR: str(manifests["state"]),
                     instruction_bridge.SELECTOR: str(manifests["instructions"])}
        oracle = types.ModuleType("hia_code_original_e09")
        original = (root / "tests/fixtures/hia_machine_x64_e09.py.txt").read_bytes()
        if sha256(original).hexdigest() != "8795fb4e5034673401f5f6a5a60e57872c48a3982dbdcb4d3b8198ee7b3f41a9":
            raise AssertionError("original whole Code source changed")
        exec(compile(original, "hia_machine_x64_e09.py.txt", "exec"), oracle.__dict__)
        cases = ("emit-data-temporary", "labels-membership-temporary", "ignored-emit-result-and-reentry",
                 "move-option-temporary", "register-mapping-temporary")
        for case in cases:
            expected = observation(oracle.Code, case)
            with guarded_selection(reference, byte_bridge, selectors):
                actual = observation(reference.Code, case)
            row = {"case": case, "expected": expected, "actual": actual, "equal": expected == actual}
            report["differentials"].append(row)
            write(target, report)
            print(json.dumps({"case": case, "equal": row["equal"]}), flush=True)
        report["issued_frame_mutation"] = mutation_permission(state_bridge, images["state"])
        report["ack_store_interruption"] = acknowledgement_interruption(state_bridge, images["state"])
        report["native_entries"] = {kind: dict(image.transitions) for kind, image in images.items() if hasattr(image, "transitions")}
        report["native_encoding_calls"] = dict(images["encoding"].calls)
        report["status"] = "PASS" if (all(row["equal"] for row in report["differentials"])
            and report["issued_frame_mutation"]["control_pass"]
            and report["ack_store_interruption"]["control_pass"]) else "FAIL_WITH_ACTUAL_DIFFERENCES"
    except BaseException:
        report["status"] = "ERROR"
        report["exception"] = traceback.format_exc()
        traceback.print_exc()
    finally:
        report["seconds"] = time.monotonic() - started
        report["source_after"] = {name: identity((root / name).read_bytes()) for name in pins}
        report["source_unchanged"] = report["source_after"] == pins
        report["compiler_unchanged"] = compiler.read_bytes() == compiler_raw
        if not report["source_unchanged"] or not report["compiler_unchanged"]:
            report["status"] = "ERROR_INPUT_CHANGED"
        write(target, report)
        print(json.dumps({"status": report["status"], "seconds": report["seconds"],
                          "source_unchanged": report["source_unchanged"],
                          "compiler_unchanged": report["compiler_unchanged"],
                          "report": str(target)}), flush=True)
    return 0 if report["status"] == "PASS" else 1

if __name__ == "__main__":
    raise SystemExit(main())

"""Bounded current-component development gate; never a cold/full certificate."""
import argparse
from hashlib import sha256
import json,os,platform,sys,time,traceback,unittest
from pathlib import Path

def write(p,v):p.write_text(json.dumps(v,sort_keys=True,indent=2)+'\n')
def snapshot(root):
    return {p.relative_to(root).as_posix():{'bytes':p.stat().st_size,'sha256':sha256(p.read_bytes()).hexdigest()}
      for p in sorted(root.rglob('*')) if p.is_file()
      and p.relative_to(root).parts[0]!='development-evidence'
      and '__pycache__' not in p.parts}
def flatten(s):
    for t in s:
        if isinstance(t,unittest.TestSuite):yield from flatten(t)
        else:yield t
def main():
    p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--bundle-root',type=Path,required=True)
    args=p.parse_args();root=args.source.resolve(strict=True);out=args.output.resolve();out.mkdir(mode=0o700,parents=True,exist_ok=False)
    sys.path.insert(0,str(root));os.chdir(root)
    removed=sorted(k for k in os.environ if k.startswith('HEPTA_'))
    for k in removed:del os.environ[k]
    os.environ['PYTHONDONTWRITEBYTECODE']='1'
    bundle={part+'_manifest':str((args.bundle_root/part/'manifest.json').resolve(strict=True)) for part in ('encoding','state','instructions')}
    bundlefile=out/'bundle.json';write(bundlefile,bundle)
    for part in ('STATE','INSTRUCTIONS'):
        os.environ['HEPTA_HIA_MACHINE_'+part+'_DEVELOPMENT_BUNDLE']=str(bundlefile)
        os.environ['HEPTA_HIA_MACHINE_'+part+'_FIXTURE_EVIDENCE']=str(out/part.lower())
    os.environ['HEPTA_HIA_MACHINE_ENCODING_DEVELOPMENT_MANIFEST']=bundle['encoding_manifest']
    os.environ['HEPTA_HIA_MACHINE_ENCODING_FIXTURE_EVIDENCE']=str(out/'encoding')
    modules=['tests.test_hia_machine_encoding_native','tests.test_hia_machine_state_native','tests.test_hia_machine_instructions_native']
    inputs={}
    for part in ('encoding','state','instructions'):
        m=Path(bundle[part+'_manifest']);v=json.loads(m.read_bytes())
        for f in (m,m.parent/v['image_path']):
            raw=f.read_bytes();inputs[str(f)]={'bytes':len(raw),'sha256':sha256(raw).hexdigest()}
    report={'schema':'hepta.hia.code-component-gate.v75-r2','status':'RUNNING','python':sys.version,'platform':platform.platform(),
      'source_is_complete_checkout':False,'scope':'RETAINED_81B6_COMPILER_COMPONENT_DEVELOPMENT',
      'source_before':snapshot(root),'inputs_before':inputs,'removed_selector_names':removed,'modules':modules,
      'cold_qualified':False,'whole_native_qualified':False,'default_flipped':False,'legacy_deleted':False}
    write(out/'REPORT.json',report);started=time.monotonic()
    executed=[];loader=unittest.TestLoader()
    try:
        suite=loader.loadTestsFromNames(modules);ids=[t.id() for t in flatten(suite)]
        report.update(loaded_ids=ids,loader_errors=list(loader.errors))
        if loader.errors or len(ids)!=33 or len(set(ids))!=33:raise AssertionError('original three complete component modules must load exactly 33 unique methods')
        class Result(unittest.TextTestResult):
            def startTest(self,t):executed.append(t.id());super().startTest(t)
        with (out/'unittest.log').open('w') as log:
            result=unittest.TextTestRunner(stream=log,verbosity=2,resultclass=Result).run(suite)
        fields={k:len(getattr(result,k)) for k in ('failures','errors','skipped','expectedFailures','unexpectedSuccesses')}
        report.update(tests_run=result.testsRun,executed_ids=executed,counts=fields,
          failures=[{'test':t.id(),'traceback':s} for t,s in result.failures],
          errors=[{'test':t.id(),'traceback':s} for t,s in result.errors])
        report['status']='PASS' if result.testsRun==33 and executed==ids and not any(fields.values()) else 'FAIL'
    except BaseException:
        report['status']='ERROR';report['exception']=traceback.format_exc()
    finally:
        report['seconds']=time.monotonic()-started
        report['source_after']=snapshot(root);report['source_unchanged']=report['source_before']==report['source_after']
        report['inputs_after']={p:{'bytes':len(Path(p).read_bytes()),'sha256':sha256(Path(p).read_bytes()).hexdigest()} for p in inputs}
        report['inputs_unchanged']=inputs==report['inputs_after']
        if not report['source_unchanged'] or not report['inputs_unchanged']:report['status']='ERROR_INPUT_CHANGED'
        write(out/'REPORT.json',report)
        print(json.dumps({k:report[k] for k in ('status','seconds','source_unchanged','inputs_unchanged')},sort_keys=True),flush=True)
    return 0 if report['status']=='PASS' else 1
if __name__=='__main__':raise SystemExit(main())
